// === Tab: mySketch ===
let amountParticles = 300;
let allParticles = [amountParticles];
let colourinRadians;
let goToMouse = false;
let easing = 0.05;
let particleSize = 10;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);
	colourinRadians = TWO_PI/255;
	for (let i = 0; i < amountParticles; i++) {
		allParticles[i] = new particle(i, amountParticles, particleSize);
	}
}

function draw() {
	background(100);
	for (let particle of allParticles) {
		particle.update(goToMouse);
		particle.draw();
	}
}

function mouseReleased() {
    goToMouse = !goToMouse;
}

// === Tab: Particle ===
class particle {
	constructor(_pNum, _amountParticles, _particleSize) {
		this.amountParticles = _amountParticles;
		this.pNum = _pNum*(TWO_PI/this.amountParticles);//Particle Number
		this.particleSize = _particleSize;
		this.radius = random(20, 75); // This is the moving area of object

		this.pos = createVector(random(0, width), random(0, height));
		this.origPos = this.pos;
		this.moveArea = createVector(this.radius*sin(this.pNum),this.radius*cos(this.pNum));
		this.particlePos = p5.Vector.add(this.pos, this.moveArea); // Pos and moveArea change on their own and therefore cannot be final pos
	}

	update(_goToMouse){
		let mousPos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		if(_goToMouse){ // track down the mouse position
			this.goToMouse = _goToMouse;
			this.pos = this.easingF(this.pos, mousPos);
			this.radius = random(25, 75);
			this.updateMoveArea();
			 }
		else if(this.goToMouse){ // go back to where you started
			this.pos = this.easingF(this.pos, this.origPos);
			this.particlePos = p5.Vector.add(this.pos, this.moveArea);

			// When the blob is back home and the mouse has given it life again
			if(p5.Vector.dist(this.pos, this.origPos) <=2 && p5.Vector.dist(this.particlePos, mousPos) <= this.particleSize)
					this.goToMouse = false;

		}
		else{
				this.pNum += 0.01;
				this.updateMoveArea();
		}
	}
	draw() {		
		colorMode(HSB, 100);
		noStroke();
		if(this.goToMouse)
			fill(255, 100, 0);
		else
			fill(abs(sin(this.pNum)*100), 100, 100);

		rect(this.particlePos.x-this.particleSize, this.particlePos.y-this.particleSize, this.particleSize*2);
	}

	easingF(_pos, _targetPos){
  	let dist = p5.Vector.sub(_targetPos, _pos);		
		return p5.Vector.add(_pos, p5.Vector.mult(dist, easing));
	}

	updateMoveArea(){
					this.moveArea = createVector(this.radius* sin(this.pNum), this.radius * cos(this.pNum));
					this.particlePos = p5.Vector.add(this.pos, this.moveArea);
	}
}

